//! Minimal unicode helpers: display width and grapheme segmentation.

use crate::tables::{GC_CONTROL, GC_EXTEND, GC_SPACING, WIDE, ZERO_WIDTH};

fn in_table(c: u32, table: &[(u32, u32)]) -> bool {
    let mut lo = 0usize;
    let mut hi = table.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (a, b) = table[mid];
        if c < a {
            hi = mid;
        } else if c > b {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    false
}

/// Width of a single character, `None` for control characters.
pub fn char_width(ch: char) -> Option<usize> {
    let c = ch as u32;
    if c == 0 {
        return Some(0);
    }
    if c < 0x20 || (0x7f..0xa0).contains(&c) {
        return None;
    }
    if c < 0x7f {
        return Some(1);
    }
    if in_table(c, ZERO_WIDTH) {
        return Some(0);
    }
    if in_table(c, WIDE) {
        return Some(2);
    }
    Some(1)
}

/// Display width of a string (control characters count as zero).
pub fn str_width(s: &str) -> usize {
    s.chars().map(|c| char_width(c).unwrap_or(0)).sum()
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Gb {
    Cr,
    Lf,
    Control,
    Extend,
    Zwj,
    Ri,
    Spacing,
    L,
    V,
    T,
    Lv,
    Lvt,
    Pict,
    Other,
}

fn gb_class(ch: char) -> Gb {
    let c = ch as u32;
    if c == 0x0d {
        return Gb::Cr;
    }
    if c == 0x0a {
        return Gb::Lf;
    }
    if c < 0x7f {
        if c < 0x20 {
            return Gb::Control;
        }
        return Gb::Other;
    }
    if c == 0x200d {
        return Gb::Zwj;
    }
    if (0x1f1e6..=0x1f1ff).contains(&c) {
        return Gb::Ri;
    }
    if (0x1100..=0x115f).contains(&c) || (0xa960..=0xa97c).contains(&c) {
        return Gb::L;
    }
    if (0x1160..=0x11a7).contains(&c) || (0xd7b0..=0xd7c6).contains(&c) {
        return Gb::V;
    }
    if (0x11a8..=0x11ff).contains(&c) || (0xd7cb..=0xd7fb).contains(&c) {
        return Gb::T;
    }
    if (0xac00..=0xd7a3).contains(&c) {
        if (c - 0xac00) % 28 == 0 {
            return Gb::Lv;
        }
        return Gb::Lvt;
    }
    if in_table(c, GC_CONTROL) {
        return Gb::Control;
    }
    if in_table(c, GC_EXTEND) {
        return Gb::Extend;
    }
    if in_table(c, GC_SPACING) {
        return Gb::Spacing;
    }
    if (0x1f000..=0x1faff).contains(&c)
        || (0x2600..=0x27bf).contains(&c)
        || (0x2300..=0x23ff).contains(&c)
        || (0x2b00..=0x2bff).contains(&c)
        || c == 0x00a9
        || c == 0x00ae
        || c == 0x203c
        || c == 0x2049
        || c == 0x2122
        || c == 0x2139
        || (0x2194..=0x21aa).contains(&c)
    {
        return Gb::Pict;
    }
    Gb::Other
}

/// Split a string into (approximate) extended grapheme clusters.
pub fn graphemes(s: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let mut start = 0usize;
    let mut prev: Option<Gb> = None;
    let mut ri_count = 0usize;
    let mut pict_zwj = false; // saw Pict Extend* ZWJ
    let mut in_pict = false; // inside Pict Extend*
    for (i, ch) in s.char_indices() {
        let cls = gb_class(ch);
        let brk = match prev {
            None => false,
            Some(p) => {
                if p == Gb::Cr && cls == Gb::Lf {
                    false
                } else if matches!(p, Gb::Cr | Gb::Lf | Gb::Control) {
                    true
                } else if matches!(cls, Gb::Cr | Gb::Lf | Gb::Control) {
                    true
                } else if p == Gb::L && matches!(cls, Gb::L | Gb::V | Gb::Lv | Gb::Lvt) {
                    false
                } else if matches!(p, Gb::Lv | Gb::V) && matches!(cls, Gb::V | Gb::T) {
                    false
                } else if matches!(p, Gb::Lvt | Gb::T) && cls == Gb::T {
                    false
                } else if matches!(cls, Gb::Extend | Gb::Zwj | Gb::Spacing) {
                    false
                } else if p == Gb::Zwj && cls == Gb::Pict && pict_zwj {
                    false
                } else if p == Gb::Ri && cls == Gb::Ri && ri_count % 2 == 1 {
                    false
                } else {
                    true
                }
            }
        };
        if brk {
            out.push(&s[start..i]);
            start = i;
        }
        // update state
        if cls == Gb::Ri {
            if prev == Some(Gb::Ri) && !brk {
                ri_count += 1;
            } else {
                ri_count = 1;
            }
        } else {
            ri_count = 0;
        }
        match cls {
            Gb::Pict => {
                in_pict = true;
                pict_zwj = false;
            }
            Gb::Extend => {
                pict_zwj = false;
            }
            Gb::Zwj => {
                pict_zwj = in_pict;
                in_pict = false;
            }
            _ => {
                in_pict = false;
                pict_zwj = false;
            }
        }
        if cls == Gb::Extend && prev.is_some() {
            // keep in_pict state across Extend characters
        }
        prev = Some(cls);
    }
    if start < s.len() {
        out.push(&s[start..]);
    }
    out
}
EOF
