//! A small terminal UI toolkit: buffers, styles, layout and widgets.

use crate::unicode::{graphemes, str_width};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub struct Rect {
    pub x: u16,
    pub y: u16,
    pub width: u16,
    pub height: u16,
}

impl Rect {
    /// Creates a rect, clipping its area so it fits in a u16 cell count.
    pub fn new(x: u16, y: u16, width: u16, height: u16) -> Rect {
        let max_area = u16::MAX;
        let (w, h) = if (width as u32) * (height as u32) > max_area as u32 {
            let aspect_ratio = width as f64 / height as f64;
            let max_area_f = max_area as f64;
            let height_f = (max_area_f / aspect_ratio).sqrt();
            let width_f = height_f * aspect_ratio;
            (width_f as u16, height_f as u16)
        } else {
            (width, height)
        };
        Rect { x, y, width: w, height: h }
    }
    pub fn area(&self) -> u16 {
        self.width.wrapping_mul(self.height)
    }
    pub fn left(&self) -> u16 {
        self.x
    }
    pub fn right(&self) -> u16 {
        self.x.saturating_add(self.width)
    }
    pub fn top(&self) -> u16 {
        self.y
    }
    pub fn bottom(&self) -> u16 {
        self.y.saturating_add(self.height)
    }
    pub fn inner(&self, h_margin: u16, v_margin: u16) -> Rect {
        if self.width < 2 * h_margin || self.height < 2 * v_margin {
            Rect::default()
        } else {
            Rect {
                x: self.x + h_margin,
                y: self.y + v_margin,
                width: self.width - 2 * h_margin,
                height: self.height - 2 * v_margin,
            }
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Color {
    Reset,
    Red,
    Green,
    Magenta,
}

pub const BOLD: u16 = 1;
pub const DIM: u16 = 2;
pub const ITALIC: u16 = 4;
pub const UNDERLINED: u16 = 8;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub add: u16,
    pub sub: u16,
}

impl Style {
    pub fn new() -> Style {
        Style::default()
    }
    pub fn fg(mut self, c: Color) -> Style {
        self.fg = Some(c);
        self
    }
    pub fn add_modifier(mut self, m: u16) -> Style {
        self.sub &= !m;
        self.add |= m;
        self
    }
    pub fn patch(mut self, other: Style) -> Style {
        if other.fg.is_some() {
            self.fg = other.fg;
        }
        if other.bg.is_some() {
            self.bg = other.bg;
        }
        self.add &= !other.sub;
        self.add |= other.add;
        self.sub &= !other.add;
        self.sub |= other.sub;
        self
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Cell {
    pub symbol: String,
    pub fg: Color,
    pub bg: Color,
    pub modifier: u16,
}

impl Default for Cell {
    fn default() -> Cell {
        Cell { symbol: " ".to_string(), fg: Color::Reset, bg: Color::Reset, modifier: 0 }
    }
}

impl Cell {
    pub fn set_symbol(&mut self, s: &str) -> &mut Cell {
        self.symbol.clear();
        self.symbol.push_str(s);
        self
    }
    pub fn set_style(&mut self, style: Style) -> &mut Cell {
        if let Some(c) = style.fg {
            self.fg = c;
        }
        if let Some(c) = style.bg {
            self.bg = c;
        }
        self.modifier |= style.add;
        self.modifier &= !style.sub;
        self
    }
    pub fn style(&self) -> Style {
        Style { fg: Some(self.fg), bg: Some(self.bg), add: self.modifier, sub: 0 }
    }
    pub fn reset(&mut self) {
        self.symbol.clear();
        self.symbol.push(' ');
        self.fg = Color::Reset;
        self.bg = Color::Reset;
        self.modifier = 0;
    }
}

#[derive(Clone, Debug)]
pub struct Buffer {
    pub area: Rect,
    pub content: Vec<Cell>,
}

impl Buffer {
    pub fn empty(area: Rect) -> Buffer {
        let n = area.width as usize * area.height as usize;
        Buffer { area, content: vec![Cell::default(); n] }
    }
    pub fn index_of(&self, x: u16, y: u16) -> usize {
        ((y - self.area.y) as usize) * self.area.width as usize + (x - self.area.x) as usize
    }
    pub fn get_mut(&mut self, x: u16, y: u16) -> &mut Cell {
        let i = self.index_of(x, y);
        &mut self.content[i]
    }
    pub fn get(&self, x: u16, y: u16) -> &Cell {
        let i = self.index_of(x, y);
        &self.content[i]
    }
    pub fn reset(&mut self) {
        for c in self.content.iter_mut() {
            c.reset();
        }
    }
    pub fn resize(&mut self, area: Rect) {
        let n = area.width as usize * area.height as usize;
        if self.content.len() > n {
            self.content.truncate(n);
        } else {
            self.content.resize(n, Cell::default());
        }
        self.area = area;
    }
    pub fn set_style(&mut self, area: Rect, style: Style) {
        for y in area.top()..area.bottom() {
            for x in area.left()..area.right() {
                self.get_mut(x, y).set_style(style);
            }
        }
    }
    pub fn set_stringn(&mut self, x: u16, y: u16, string: &str, width: usize, style: Style) -> (u16, u16) {
        let mut index = self.index_of(x, y);
        let mut x_offset = x as usize;
        let max_offset = std::cmp::min(self.area.right() as usize, width.saturating_add(x as usize));
        for g in graphemes(string) {
            let w = str_width(g);
            if w == 0 {
                continue;
            }
            if w > max_offset.saturating_sub(x_offset) {
                break;
            }
            self.content[index].set_symbol(g);
            self.content[index].set_style(style);
            for i in index + 1..index + w {
                self.content[i].reset();
            }
            index += w;
            x_offset += w;
        }
        (x_offset as u16, y)
    }
    pub fn set_span(&mut self, x: u16, y: u16, span: &Span, width: u16) -> (u16, u16) {
        self.set_stringn(x, y, &span.content, width as usize, span.style)
    }
    pub fn set_spans(&mut self, x: u16, y: u16, spans: &[Span], width: u16) -> (u16, u16) {
        let mut remaining_width = width;
        let mut x = x;
        for span in spans {
            if remaining_width == 0 {
                break;
            }
            let pos = self.set_stringn(x, y, &span.content, remaining_width as usize, span.style);
            let w = pos.0.saturating_sub(x);
            x = pos.0;
            remaining_width = remaining_width.saturating_sub(w);
        }
        (x, y)
    }

    /// Cells that differ between `self` (previous) and `other` (next).
    pub fn diff<'a>(&self, other: &'a Buffer) -> Vec<(u16, u16, &'a Cell)> {
        let prev = &self.content;
        let next = &other.content;
        let width = self.area.width;
        let mut updates = Vec::new();
        let mut invalidated: usize = 0;
        let mut to_skip: usize = 0;
        for (i, (current, previous)) in next.iter().zip(prev.iter()).enumerate() {
            if (current != previous || invalidated > 0) && to_skip == 0 {
                let x = (i as u16) % width;
                let y = (i as u16) / width;
                updates.push((x, y, &next[i]));
            }
            to_skip = str_width(&current.symbol).saturating_sub(1);
            let affected_width = std::cmp::max(str_width(&current.symbol), str_width(&previous.symbol));
            invalidated = std::cmp::max(affected_width, invalidated).saturating_sub(1);
        }
        updates
    }
}

#[derive(Clone, Debug)]
pub struct Span {
    pub content: String,
    pub style: Style,
}

impl Span {
    pub fn styled<S: Into<String>>(s: S, style: Style) -> Span {
        Span { content: s.into(), style }
    }
    pub fn raw<S: Into<String>>(s: S) -> Span {
        Span { content: s.into(), style: Style::default() }
    }
    pub fn width(&self) -> usize {
        str_width(&self.content)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Constraint {
    Length(u16),
    Min(u16),
}

/// Vertical layout. Mirrors the results produced by the constraint solver
/// for the layouts used in this program: chunks are allocated in order,
/// the first `Min` constraint (or else the last chunk) absorbs extra room.
pub fn layout_vertical(area: Rect, h_margin: u16, v_margin: u16, constraints: &[Constraint]) -> Vec<Rect> {
    let dest = area.inner(h_margin, v_margin);
    let n = constraints.len();
    let desired: Vec<u32> = constraints
        .iter()
        .map(|c| match c {
            Constraint::Length(v) => *v as u32,
            Constraint::Min(v) => *v as u32,
        })
        .collect();
    let total: u32 = desired.iter().sum();
    let avail = dest.height as u32;
    let mut heights = vec![0u32; n];
    if total <= avail {
        heights.copy_from_slice(&desired);
        let extra = avail - total;
        if let Some(i) = constraints.iter().position(|c| matches!(c, Constraint::Min(_))) {
            heights[i] += extra;
        } else if n > 0 {
            heights[n - 1] += extra;
        }
    } else {
        let mut remaining = avail;
        for i in 0..n {
            if i == n - 1 {
                heights[i] = remaining;
            } else {
                let h = desired[i].min(remaining);
                heights[i] = h;
                remaining -= h;
            }
        }
    }
    let mut out = Vec::with_capacity(n);
    let mut y = dest.y as u32;
    for h in heights {
        out.push(Rect { x: dest.x, y: y as u16, width: dest.width, height: h as u16 });
        y += h;
    }
    out
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Alignment {
    Left,
    Center,
    Right,
}

#[derive(Clone)]
struct StyledGrapheme<'a> {
    symbol: &'a str,
    style: Style,
}

fn is_ws(s: &str) -> bool {
    s.chars().all(char::is_whitespace)
}

struct WordWrapper<'a> {
    symbols: std::vec::IntoIter<StyledGrapheme<'a>>,
    max_line_width: u16,
    current_line: Vec<StyledGrapheme<'a>>,
    next_line: Vec<StyledGrapheme<'a>>,
    trim: bool,
}

impl<'a> WordWrapper<'a> {
    fn next_line(&mut self) -> Option<(Vec<StyledGrapheme<'a>>, u16)> {
        if self.max_line_width == 0 {
            return None;
        }
        std::mem::swap(&mut self.current_line, &mut self.next_line);
        self.next_line.truncate(0);

        let mut current_line_width: u16 = self.current_line.iter().map(|g| str_width(g.symbol) as u16).sum();

        let mut symbols_to_last_word_end: usize = 0;
        let mut width_to_last_word_end: u16 = 0;
        let mut prev_whitespace = false;
        let mut symbols_exhausted = true;
        while let Some(StyledGrapheme { symbol, style }) = self.symbols.next() {
            symbols_exhausted = false;
            let symbol_whitespace = is_ws(symbol);

            if str_width(symbol) as u16 > self.max_line_width
                || self.trim && symbol_whitespace && symbol != "\n" && current_line_width == 0
            {
                continue;
            }

            if symbol == "\n" {
                if prev_whitespace {
                    current_line_width = width_to_last_word_end;
                    self.current_line.truncate(symbols_to_last_word_end);
                }
                break;
            }

            if symbol_whitespace && !prev_whitespace {
                symbols_to_last_word_end = self.current_line.len();
                width_to_last_word_end = current_line_width;
            }

            self.current_line.push(StyledGrapheme { symbol, style });
            current_line_width += str_width(symbol) as u16;

            if current_line_width > self.max_line_width {
                let (truncate_at, truncated_width) = if symbols_to_last_word_end != 0 {
                    (symbols_to_last_word_end, width_to_last_word_end)
                } else {
                    (self.current_line.len() - 1, self.max_line_width)
                };
                {
                    let remainder = &self.current_line[truncate_at..];
                    if let Some(pos) = remainder.iter().position(|g| !is_ws(g.symbol)) {
                        let rest: Vec<StyledGrapheme<'a>> = remainder[pos..].to_vec();
                        self.next_line.extend(rest);
                    }
                }
                self.current_line.truncate(truncate_at);
                current_line_width = truncated_width;
                break;
            }

            prev_whitespace = symbol_whitespace;
        }

        if symbols_exhausted && self.current_line.is_empty() {
            None
        } else {
            Some((self.current_line.clone(), current_line_width))
        }
    }
}

struct LineTruncator<'a> {
    symbols: std::vec::IntoIter<StyledGrapheme<'a>>,
    max_line_width: u16,
}

impl<'a> LineTruncator<'a> {
    fn next_line(&mut self) -> Option<(Vec<StyledGrapheme<'a>>, u16)> {
        if self.max_line_width == 0 {
            return None;
        }
        let mut current_line = Vec::new();
        let mut current_line_width: u16 = 0;
        let mut skip_rest = false;
        let mut symbols_exhausted = true;
        while let Some(StyledGrapheme { symbol, style }) = self.symbols.next() {
            symbols_exhausted = false;
            let w = str_width(symbol) as u16;
            if w > self.max_line_width {
                continue;
            }
            if symbol == "\n" {
                break;
            }
            if current_line_width + w > self.max_line_width {
                skip_rest = true;
                break;
            }
            current_line_width += w;
            current_line.push(StyledGrapheme { symbol, style });
        }
        if skip_rest {
            for g in self.symbols.by_ref() {
                if g.symbol == "\n" {
                    break;
                }
            }
        }
        if symbols_exhausted {
            None
        } else {
            Some((current_line, current_line_width))
        }
    }
}

fn get_line_offset(line_width: u16, text_area_width: u16, alignment: Alignment) -> u16 {
    match alignment {
        Alignment::Center => (text_area_width / 2).saturating_sub(line_width / 2),
        Alignment::Right => text_area_width.saturating_sub(line_width),
        Alignment::Left => 0,
    }
}

/// Renders a single line of spans as a paragraph.
pub fn render_paragraph(buf: &mut Buffer, area: Rect, spans: &[Span], alignment: Alignment, wrap_trim: Option<bool>) {
    let text_area = area;
    if text_area.height < 1 {
        return;
    }
    let mut styled: Vec<StyledGrapheme> = Vec::new();
    for span in spans {
        for g in graphemes(&span.content) {
            if g == "\n" {
                continue;
            }
            styled.push(StyledGrapheme { symbol: g, style: Style::default().patch(span.style) });
        }
    }
    styled.push(StyledGrapheme { symbol: "\n", style: Style::default() });

    enum Composer<'a> {
        Wrap(WordWrapper<'a>),
        Trunc(LineTruncator<'a>),
    }
    let mut composer = match wrap_trim {
        Some(trim) => Composer::Wrap(WordWrapper {
            symbols: styled.into_iter(),
            max_line_width: text_area.width,
            current_line: Vec::new(),
            next_line: Vec::new(),
            trim,
        }),
        None => Composer::Trunc(LineTruncator { symbols: styled.into_iter(), max_line_width: text_area.width }),
    };
    let mut y: u16 = 0;
    loop {
        let next = match &mut composer {
            Composer::Wrap(w) => w.next_line(),
            Composer::Trunc(t) => t.next_line(),
        };
        let (line, line_width) = match next {
            Some(v) => v,
            None => break,
        };
        let mut x = get_line_offset(line_width, text_area.width, alignment);
        for g in line {
            let sym = if g.symbol.is_empty() { " " } else { g.symbol };
            buf.get_mut(text_area.left() + x, text_area.top() + y).set_symbol(sym).set_style(g.style);
            x += str_width(g.symbol) as u16;
        }
        y += 1;
        if y >= text_area.height {
            break;
        }
    }
}

const BRAILLE_DOTS: [[u16; 2]; 4] = [[0x0001, 0x0008], [0x0002, 0x0010], [0x0004, 0x0020], [0x0040, 0x0080]];
const BRAILLE_BLANK: u16 = 0x2800;

struct BrailleGrid {
    width: u16,
    height: u16,
    cells: Vec<u16>,
    colors: Vec<Color>,
}

impl BrailleGrid {
    fn new(width: u16, height: u16) -> BrailleGrid {
        let length = width as usize * height as usize;
        BrailleGrid { width, height, cells: vec![BRAILLE_BLANK; length], colors: vec![Color::Reset; length] }
    }
    fn resolution(&self) -> (f64, f64) {
        (self.width as f64 * 2.0 - 1.0, self.height as f64 * 4.0 - 1.0)
    }
    fn paint(&mut self, x: usize, y: usize, color: Color) {
        let index = y / 4 * self.width as usize + x / 2;
        if let Some(c) = self.cells.get_mut(index) {
            *c |= BRAILLE_DOTS[y % 4][x % 2];
        }
        if let Some(c) = self.colors.get_mut(index) {
            *c = color;
        }
    }
}

struct Painter {
    grid: BrailleGrid,
    x_bounds: [f64; 2],
    y_bounds: [f64; 2],
}

impl Painter {
    fn get_point(&self, x: f64, y: f64) -> Option<(usize, usize)> {
        let left = self.x_bounds[0];
        let right = self.x_bounds[1];
        let top = self.y_bounds[1];
        let bottom = self.y_bounds[0];
        if x < left || x > right || y < bottom || y > top {
            return None;
        }
        let width = (self.x_bounds[1] - self.x_bounds[0]).abs();
        let height = (self.y_bounds[1] - self.y_bounds[0]).abs();
        if width == 0.0 || height == 0.0 {
            return None;
        }
        let res = self.grid.resolution();
        let x = ((x - left) * res.0 / width) as usize;
        let y = ((top - y) * res.1 / height) as usize;
        Some((x, y))
    }
    fn paint(&mut self, x: usize, y: usize, color: Color) {
        self.grid.paint(x, y, color);
    }
}

fn draw_line_low(p: &mut Painter, x1: usize, y1: usize, x2: usize, y2: usize, color: Color) {
    let dx = (x2 - x1) as isize;
    let dy = (y2 as isize - y1 as isize).abs();
    let mut d = 2 * dy - dx;
    let mut y = y1;
    for x in x1..=x2 {
        p.paint(x, y, color);
        if d > 0 {
            y = if y1 > y2 { y.saturating_sub(1) } else { y.saturating_add(1) };
            d -= 2 * dx;
        }
        d += 2 * dy;
    }
}

fn draw_line_high(p: &mut Painter, x1: usize, y1: usize, x2: usize, y2: usize, color: Color) {
    let dx = (x2 as isize - x1 as isize).abs();
    let dy = (y2 - y1) as isize;
    let mut d = 2 * dx - dy;
    let mut x = x1;
    for y in y1..=y2 {
        p.paint(x, y, color);
        if d > 0 {
            x = if x1 > x2 { x.saturating_sub(1) } else { x.saturating_add(1) };
            d -= 2 * dy;
        }
        d += 2 * dx;
    }
}

fn draw_line(p: &mut Painter, a: (f64, f64), b: (f64, f64), color: Color) {
    let (x1, y1) = match p.get_point(a.0, a.1) {
        Some(c) => c,
        None => return,
    };
    let (x2, y2) = match p.get_point(b.0, b.1) {
        Some(c) => c,
        None => return,
    };
    let (dx, x_lo, x_hi) = if x2 >= x1 { (x2 - x1, x1, x2) } else { (x1 - x2, x2, x1) };
    let (dy, y_lo, y_hi) = if y2 >= y1 { (y2 - y1, y1, y2) } else { (y1 - y2, y2, y1) };
    if dx == 0 {
        for y in y_lo..=y_hi {
            p.paint(x1, y, color);
        }
        return;
    }
    if dy == 0 {
        for x in x_lo..=x_hi {
            p.paint(x, y1, color);
        }
        return;
    }
    if dy < dx {
        if x1 > x2 {
            draw_line_low(p, x2, y2, x1, y1, color);
        } else {
            draw_line_low(p, x1, y1, x2, y2, color);
        }
    } else if y1 > y2 {
        draw_line_high(p, x2, y2, x1, y1, color);
    } else {
        draw_line_high(p, x1, y1, x2, y2, color);
    }
}

pub struct Axis {
    pub title: Option<Span>,
    pub bounds: [f64; 2],
    pub labels: Option<Vec<Span>>,
}

pub struct Dataset<'a> {
    pub name: String,
    pub data: &'a [(f64, f64)],
    pub color: Color,
}

#[derive(Default)]
struct ChartLayout {
    title_x: Option<(u16, u16)>,
    title_y: Option<(u16, u16)>,
    label_x: Option<u16>,
    label_y: Option<u16>,
    axis_x: Option<u16>,
    axis_y: Option<u16>,
    legend_area: Option<Rect>,
    graph_area: Rect,
}

pub struct Chart<'a> {
    pub x_axis: Axis,
    pub y_axis: Axis,
    pub datasets: Vec<Dataset<'a>>,
}

impl<'a> Chart<'a> {
    fn max_width_of_labels_left_of_y_axis(&self, area: Rect, has_y_axis: bool) -> u16 {
        let mut max_width = self
            .y_axis
            .labels
            .as_ref()
            .map(|l| l.iter().map(|s| s.width()).max().unwrap_or_default() as u16)
            .unwrap_or_default();
        if let Some(first_x_label) = self.x_axis.labels.as_ref().and_then(|labels| labels.first()) {
            let first_label_width = first_x_label.width() as u16;
            let y_axis_offset = if has_y_axis { 1 } else { 0 };
            let width_left_of_y_axis = first_label_width.saturating_sub(y_axis_offset);
            max_width = std::cmp::max(max_width, width_left_of_y_axis);
        }
        max_width.min(area.width / 3)
    }

    fn layout(&self, area: Rect) -> ChartLayout {
        let mut layout = ChartLayout::default();
        if area.height == 0 || area.width == 0 {
            return layout;
        }
        let mut x = area.left();
        let mut y = area.bottom() - 1;

        if self.x_axis.labels.is_some() && y > area.top() {
            layout.label_x = Some(y);
            y -= 1;
        }

        layout.label_y = self.y_axis.labels.as_ref().and(Some(x));
        x += self.max_width_of_labels_left_of_y_axis(area, self.y_axis.labels.is_some());

        if self.x_axis.labels.is_some() && y > area.top() {
            layout.axis_x = Some(y);
            y -= 1;
        }

        if self.y_axis.labels.is_some() && x + 1 < area.right() {
            layout.axis_y = Some(x);
            x += 1;
        }

        if x < area.right() && y > 1 {
            layout.graph_area = Rect::new(x, area.top(), area.right() - x, y - area.top() + 1);
        }

        if let Some(ref title) = self.x_axis.title {
            let w = title.width() as u16;
            if w < layout.graph_area.width && layout.graph_area.height > 2 {
                layout.title_x = Some((x + layout.graph_area.width - w, y));
            }
        }

        if let Some(ref title) = self.y_axis.title {
            let w = title.width() as u16;
            if w + 1 < layout.graph_area.width && layout.graph_area.height > 2 {
                layout.title_y = Some((x, area.top()));
            }
        }

        if let Some(inner_width) = self.datasets.iter().map(|d| str_width(&d.name) as u16).max() {
            let legend_width = inner_width + 2;
            let legend_height = self.datasets.len() as u16 + 2;
            let max_legend_width = layout.graph_area.width / 4;
            let max_legend_height = layout.graph_area.height / 4;
            if inner_width > 0 && legend_width < max_legend_width && legend_height < max_legend_height {
                layout.legend_area = Some(Rect::new(
                    layout.graph_area.right() - legend_width,
                    layout.graph_area.top(),
                    legend_width,
                    legend_height,
                ));
            }
        }
        layout
    }

    fn render_label(buf: &mut Buffer, label: &Span, label_area: Rect, alignment: Alignment) {
        let label_width = label.width() as u16;
        let bounded_label_width = label_area.width.min(label_width);
        let x = match alignment {
            Alignment::Left => label_area.left(),
            Alignment::Center => label_area.left() + label_area.width / 2 - bounded_label_width / 2,
            Alignment::Right => label_area.right() - bounded_label_width,
        };
        buf.set_span(x, label_area.top(), label, bounded_label_width);
    }

    fn render_x_labels(&self, buf: &mut Buffer, layout: &ChartLayout, chart_area: Rect, graph_area: Rect) {
        let y = match layout.label_x {
            Some(y) => y,
            None => return,
        };
        let labels = self.x_axis.labels.as_ref().unwrap();
        let labels_len = labels.len() as u16;
        if labels_len < 2 {
            return;
        }
        let width_between_ticks = graph_area.width / labels_len;
        // first label: area from the chart's left edge to the graph's left edge
        let min_x = chart_area.left();
        let max_x = graph_area.left();
        let label_area = Rect::new(min_x, y, max_x - min_x, 1);
        Self::render_label(buf, &labels[0], label_area, Alignment::Right);

        for (i, label) in labels[1..labels.len() - 1].iter().enumerate() {
            let x = graph_area.left() + (i + 1) as u16 * width_between_ticks + 1;
            let label_area = Rect::new(x, y, width_between_ticks.saturating_sub(1), 1);
            Self::render_label(buf, label, label_area, Alignment::Center);
        }

        let x = graph_area.right() - width_between_ticks;
        let label_area = Rect::new(x, y, width_between_ticks, 1);
        Self::render_label(buf, labels.last().unwrap(), label_area, Alignment::Right);
    }

    fn render_y_labels(&self, buf: &mut Buffer, layout: &ChartLayout, chart_area: Rect, graph_area: Rect) {
        let x = match layout.label_y {
            Some(x) => x,
            None => return,
        };
        let labels = self.y_axis.labels.as_ref().unwrap();
        let labels_len = labels.len() as u16;
        let label_width = graph_area.left().saturating_sub(chart_area.left());
        for (i, label) in labels.iter().enumerate() {
            let dy = i as u16 * (graph_area.height - 1) / (labels_len - 1);
            if dy < graph_area.bottom() {
                let label_area = Rect::new(x, graph_area.bottom().saturating_sub(1) - dy, label_width, 1);
                Self::render_label(buf, label, label_area, Alignment::Left);
            }
        }
    }

    pub fn render(&self, area: Rect, buf: &mut Buffer) {
        if area.area() == 0 {
            return;
        }
        let original_style = buf.get(area.left(), area.top()).style();
        let chart_area = area;
        let layout = self.layout(chart_area);
        let graph_area = layout.graph_area;
        if graph_area.width < 1 || graph_area.height < 1 {
            return;
        }

        self.render_x_labels(buf, &layout, chart_area, graph_area);
        self.render_y_labels(buf, &layout, chart_area, graph_area);

        if let Some(y) = layout.axis_x {
            for x in graph_area.left()..graph_area.right() {
                buf.get_mut(x, y).set_symbol("\u{2500}").set_style(Style::default());
            }
        }
        if let Some(x) = layout.axis_y {
            for y in graph_area.top()..graph_area.bottom() {
                buf.get_mut(x, y).set_symbol("\u{2502}").set_style(Style::default());
            }
        }
        if let Some(y) = layout.axis_x {
            if let Some(x) = layout.axis_y {
                buf.get_mut(x, y).set_symbol("\u{2514}").set_style(Style::default());
            }
        }

        for dataset in &self.datasets {
            // canvas
            let canvas_area = graph_area;
            buf.set_style(canvas_area, Style::default().patch(Style { fg: None, bg: Some(Color::Reset), add: 0, sub: 0 }));
            let mut painter = Painter {
                grid: BrailleGrid::new(canvas_area.width, canvas_area.height),
                x_bounds: self.x_axis.bounds,
                y_bounds: self.y_axis.bounds,
            };
            for &(x, y) in dataset.data {
                if let Some((px, py)) = painter.get_point(x, y) {
                    painter.paint(px, py, dataset.color);
                }
            }
            for w in dataset.data.windows(2) {
                draw_line(&mut painter, w[0], w[1], dataset.color);
            }
            let width = canvas_area.width as usize;
            let grid = &painter.grid;
            for (i, (&cell, &color)) in grid.cells.iter().zip(grid.colors.iter()).enumerate() {
                if cell != BRAILLE_BLANK {
                    let ch = char::from_u32(cell as u32).unwrap_or(' ');
                    let (x, y) = (i % width, i / width);
                    let mut tmp = [0u8; 4];
                    let s = ch.encode_utf8(&mut tmp);
                    let c = buf.get_mut(x as u16 + canvas_area.left(), y as u16 + canvas_area.top());
                    c.set_symbol(s);
                    c.fg = color;
                }
            }
            let _ = grid.height;
        }

        if let Some(legend_area) = layout.legend_area {
            buf.set_style(legend_area, original_style);
            for (i, dataset) in self.datasets.iter().enumerate() {
                buf.set_stringn(
                    legend_area.x + 1,
                    legend_area.y + 1 + i as u16,
                    &dataset.name,
                    usize::MAX,
                    Style::default().fg(dataset.color),
                );
            }
        }

        if let Some((x, y)) = layout.title_x {
            let title = self.x_axis.title.as_ref().unwrap();
            let width = graph_area.right().saturating_sub(x);
            buf.set_style(Rect { x, y, width, height: 1 }, original_style);
            buf.set_spans(x, y, std::slice::from_ref(title), width);
        }

        if let Some((x, y)) = layout.title_y {
            let title = self.y_axis.title.as_ref().unwrap();
            let width = graph_area.right().saturating_sub(x);
            buf.set_style(Rect { x, y, width, height: 1 }, original_style);
            buf.set_spans(x, y, std::slice::from_ref(title), width);
        }
    }
}
