//! Terminal access: raw mode, size queries, input decoding and frame output.

use crate::tui::{Buffer, Cell, Color, Rect, BOLD, DIM, ITALIC, UNDERLINED};
use std::os::raw::{c_char, c_int, c_void};

#[repr(C)]
#[derive(Clone, Copy)]
pub struct Termios {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: u32,
    c_ospeed: u32,
}

#[repr(C)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

#[repr(C)]
struct PollFd {
    fd: c_int,
    events: i16,
    revents: i16,
}

extern "C" {
    fn tcgetattr(fd: c_int, t: *mut Termios) -> c_int;
    fn tcsetattr(fd: c_int, act: c_int, t: *const Termios) -> c_int;
    fn cfmakeraw(t: *mut Termios);
    fn isatty(fd: c_int) -> c_int;
    fn ioctl(fd: c_int, req: u64, ...) -> c_int;
    fn poll(fds: *mut PollFd, n: u64, timeout: c_int) -> c_int;
    fn read(fd: c_int, buf: *mut c_void, n: usize) -> isize;
    fn write(fd: c_int, buf: *const c_void, n: usize) -> isize;
    fn open(path: *const c_char, flags: c_int, ...) -> c_int;
    fn close(fd: c_int) -> c_int;
    fn pipe(fds: *mut c_int) -> c_int;
    fn signal(sig: c_int, handler: usize) -> usize;
    fn fcntl(fd: c_int, cmd: c_int, ...) -> c_int;
}

const TIOCGWINSZ: u64 = 0x5413;
const SIGWINCH: c_int = 28;
const O_RDWR: c_int = 2;
const O_NONBLOCK: c_int = 0o4000;
const F_SETFL: c_int = 4;
const F_GETFL: c_int = 3;
const POLLIN: i16 = 1;

pub fn is_tty(fd: i32) -> bool {
    unsafe { isatty(fd) == 1 }
}

pub fn enable_raw_mode(fd: i32) -> Option<Termios> {
    unsafe {
        let mut t: Termios = std::mem::zeroed();
        if tcgetattr(fd, &mut t) != 0 {
            return None;
        }
        let orig = t;
        cfmakeraw(&mut t);
        tcsetattr(fd, 0, &t);
        Some(orig)
    }
}

pub fn restore_mode(fd: i32, t: &Termios) {
    unsafe {
        tcsetattr(fd, 0, t);
    }
}

/// Terminal size as (columns, rows).
pub fn size() -> (u16, u16) {
    unsafe {
        let mut ws = WinSize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
        let path = b"/dev/tty\0";
        let fd = open(path.as_ptr() as *const c_char, O_RDWR);
        let use_fd = if fd >= 0 { fd } else { 1 };
        let r = ioctl(use_fd, TIOCGWINSZ, &mut ws as *mut WinSize);
        if fd >= 0 {
            close(fd);
        }
        if r == 0 {
            return (ws.ws_col, ws.ws_row);
        }
        (0, 0)
    }
}

static mut SIG_PIPE_W: c_int = -1;

extern "C" fn on_sigwinch(_sig: c_int) {
    unsafe {
        let b = [1u8];
        let fd = SIG_PIPE_W;
        if fd >= 0 {
            write(fd, b.as_ptr() as *const c_void, 1);
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum KeyCode {
    Backspace,
    Enter,
    Left,
    Right,
    Up,
    Down,
    Home,
    End,
    PageUp,
    PageDown,
    Tab,
    BackTab,
    Delete,
    Insert,
    F(u8),
    Char(char),
    Esc,
}

pub const MOD_SHIFT: u8 = 1;
pub const MOD_CONTROL: u8 = 2;
pub const MOD_ALT: u8 = 4;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct KeyEvent {
    pub code: KeyCode,
    pub modifiers: u8,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Event {
    Key(KeyEvent),
    Resize,
    Other,
}

enum Parsed {
    Event(Event),
    NeedMore,
    Error,
}

fn key(code: KeyCode) -> Parsed {
    Parsed::Event(Event::Key(KeyEvent { code, modifiers: 0 }))
}

fn key_mod(code: KeyCode, modifiers: u8) -> Parsed {
    Parsed::Event(Event::Key(KeyEvent { code, modifiers }))
}

fn parse_modifiers(mask: u8) -> u8 {
    let mask = mask.saturating_sub(1);
    let mut m = 0;
    if mask & 1 != 0 {
        m |= MOD_SHIFT;
    }
    if mask & 2 != 0 {
        m |= MOD_ALT;
    }
    if mask & 4 != 0 {
        m |= MOD_CONTROL;
    }
    m
}

fn parse_utf8_char(buffer: &[u8]) -> Parsed {
    match std::str::from_utf8(buffer) {
        Ok(s) => match s.chars().next() {
            Some(ch) => {
                let modifiers = if ch.is_uppercase() { MOD_SHIFT } else { 0 };
                key_mod(KeyCode::Char(ch), modifiers)
            }
            None => Parsed::Error,
        },
        Err(_) => {
            let required = match buffer[0] {
                0x00..=0x7f => 1,
                0xc0..=0xdf => 2,
                0xe0..=0xef => 3,
                0xf0..=0xf7 => 4,
                _ => return Parsed::Error,
            };
            if required > 1 && buffer.len() > 1 {
                for b in &buffer[1..] {
                    if b & !0b0011_1111 != 0b1000_0000 {
                        return Parsed::Error;
                    }
                }
            }
            if buffer.len() < required {
                Parsed::NeedMore
            } else {
                Parsed::Error
            }
        }
    }
}

fn parse_csi(buffer: &[u8]) -> Parsed {
    if buffer.len() == 2 {
        return Parsed::NeedMore;
    }
    match buffer[2] {
        b'[' => {
            if buffer.len() == 3 {
                Parsed::NeedMore
            } else {
                match buffer[3] {
                    v @ b'A'..=b'E' => key(KeyCode::F(1 + v - b'A')),
                    _ => Parsed::Error,
                }
            }
        }
        b'D' => key(KeyCode::Left),
        b'C' => key(KeyCode::Right),
        b'A' => key(KeyCode::Up),
        b'B' => key(KeyCode::Down),
        b'H' => key(KeyCode::Home),
        b'F' => key(KeyCode::End),
        b'Z' => key_mod(KeyCode::BackTab, MOD_SHIFT),
        b'M' => {
            // X10 mouse: ESC [ M Cb Cx Cy
            if buffer.len() < 6 {
                Parsed::NeedMore
            } else {
                Parsed::Event(Event::Other)
            }
        }
        b'<' => {
            // SGR mouse
            let last = *buffer.last().unwrap();
            if last == b'm' || last == b'M' {
                if buffer.len() < 4 {
                    return Parsed::Error;
                }
                let s = match std::str::from_utf8(&buffer[3..buffer.len() - 1]) {
                    Ok(s) => s,
                    Err(_) => return Parsed::Error,
                };
                let parts: Vec<&str> = s.split(';').collect();
                if parts.len() < 3 || parts.iter().take(3).any(|p| p.parse::<u16>().is_err()) {
                    return Parsed::Error;
                }
                Parsed::Event(Event::Other)
            } else {
                Parsed::NeedMore
            }
        }
        b'0'..=b'9' => {
            if buffer.len() == 3 {
                Parsed::NeedMore
            } else {
                let last = *buffer.last().unwrap();
                if !(64..=126).contains(&last) {
                    Parsed::NeedMore
                } else {
                    match last {
                        b'M' => parse_rxvt_mouse(buffer),
                        b'~' => parse_special_key(buffer),
                        b'R' => parse_cursor_position(buffer),
                        _ => parse_modifier_key(buffer),
                    }
                }
            }
        }
        _ => Parsed::Error,
    }
}

fn parse_numbers(s: &[u8]) -> Option<Vec<u32>> {
    let s = std::str::from_utf8(s).ok()?;
    let mut out = Vec::new();
    for p in s.split(';') {
        out.push(p.parse::<u32>().ok()?);
    }
    Some(out)
}

fn parse_rxvt_mouse(buffer: &[u8]) -> Parsed {
    match parse_numbers(&buffer[2..buffer.len() - 1]) {
        Some(v) if v.len() >= 3 && v[0] <= 255 && v[1] <= 65535 && v[2] <= 65535 => Parsed::Event(Event::Other),
        _ => Parsed::Error,
    }
}

fn parse_cursor_position(buffer: &[u8]) -> Parsed {
    match parse_numbers(&buffer[2..buffer.len() - 1]) {
        Some(v) if v.len() >= 2 => Parsed::Event(Event::Other),
        _ => Parsed::Error,
    }
}

fn parse_special_key(buffer: &[u8]) -> Parsed {
    let s = match std::str::from_utf8(&buffer[2..buffer.len() - 1]) {
        Ok(s) => s,
        Err(_) => return Parsed::Error,
    };
    let mut split = s.split(';');
    let first = match split.next().and_then(|x| x.parse::<u8>().ok()) {
        Some(v) => v,
        None => return Parsed::Error,
    };
    let modifiers = match split.next().and_then(|x| x.parse::<u8>().ok()) {
        Some(m) => parse_modifiers(m),
        None => 0,
    };
    let code = match first {
        1 | 7 => KeyCode::Home,
        2 => KeyCode::Insert,
        3 => KeyCode::Delete,
        4 | 8 => KeyCode::End,
        5 => KeyCode::PageUp,
        6 => KeyCode::PageDown,
        v @ 11..=15 => KeyCode::F(v - 10),
        v @ 17..=21 => KeyCode::F(v - 11),
        v @ 23..=26 => KeyCode::F(v - 12),
        v @ 28..=29 => KeyCode::F(v - 15),
        v @ 31..=34 => KeyCode::F(v - 17),
        _ => return Parsed::Error,
    };
    key_mod(code, modifiers)
}

fn parse_modifier_key(buffer: &[u8]) -> Parsed {
    let modifier_mask = buffer[buffer.len() - 2];
    let k = buffer[buffer.len() - 1];
    let modifiers = parse_modifiers(modifier_mask);
    let code = match k {
        b'A' => KeyCode::Up,
        b'B' => KeyCode::Down,
        b'C' => KeyCode::Right,
        b'D' => KeyCode::Left,
        b'F' => KeyCode::End,
        b'H' => KeyCode::Home,
        b'P' => KeyCode::F(1),
        b'Q' => KeyCode::F(2),
        b'R' => KeyCode::F(3),
        b'S' => KeyCode::F(4),
        _ => return Parsed::Error,
    };
    key_mod(code, modifiers)
}

fn parse_event(buffer: &[u8], input_available: bool) -> Parsed {
    if buffer.is_empty() {
        return Parsed::NeedMore;
    }
    match buffer[0] {
        0x1b => {
            if buffer.len() == 1 {
                if input_available {
                    Parsed::NeedMore
                } else {
                    key(KeyCode::Esc)
                }
            } else {
                match buffer[1] {
                    b'O' => {
                        if buffer.len() == 2 {
                            Parsed::NeedMore
                        } else {
                            match buffer[2] {
                                v @ b'P'..=b'S' => key(KeyCode::F(1 + v - b'P')),
                                _ => Parsed::Error,
                            }
                        }
                    }
                    b'[' => parse_csi(buffer),
                    0x1b => key(KeyCode::Esc),
                    _ => match parse_event(&buffer[1..], input_available) {
                        Parsed::Event(Event::Key(mut k)) => {
                            k.modifiers |= MOD_ALT;
                            Parsed::Event(Event::Key(k))
                        }
                        other => other,
                    },
                }
            }
        }
        b'\r' => key(KeyCode::Enter),
        b'\t' => key(KeyCode::Tab),
        0x7f => key(KeyCode::Backspace),
        c @ 0x01..=0x1a => key_mod(KeyCode::Char((c - 0x1 + b'a') as char), MOD_CONTROL),
        c @ 0x1c..=0x1f => key_mod(KeyCode::Char((c - 0x1c + b'4') as char), MOD_CONTROL),
        0 => key_mod(KeyCode::Char(' '), MOD_CONTROL),
        _ => parse_utf8_char(buffer),
    }
}

const TTY_BUFFER_SIZE: usize = 1024;

pub struct Input {
    fd: i32,
    sig_r: i32,
    parse_buf: Vec<u8>,
    pending: std::collections::VecDeque<Event>,
}

impl Input {
    pub fn new(fd: i32) -> Input {
        let mut fds = [0 as c_int; 2];
        let sig_r = unsafe {
            if pipe(fds.as_mut_ptr()) == 0 {
                let fl = fcntl(fds[0], F_GETFL);
                fcntl(fds[0], F_SETFL, fl | O_NONBLOCK);
                let fl = fcntl(fds[1], F_GETFL);
                fcntl(fds[1], F_SETFL, fl | O_NONBLOCK);
                SIG_PIPE_W = fds[1];
                signal(SIGWINCH, on_sigwinch as usize);
                fds[0]
            } else {
                -1
            }
        };
        Input { fd, sig_r, parse_buf: Vec::new(), pending: Default::default() }
    }

    fn advance(&mut self, data: &[u8], more: bool) {
        for (idx, b) in data.iter().enumerate() {
            let more = idx + 1 < data.len() || more;
            self.parse_buf.push(*b);
            match parse_event(&self.parse_buf, more) {
                Parsed::Event(ev) => {
                    self.pending.push_back(ev);
                    self.parse_buf.clear();
                }
                Parsed::NeedMore => {}
                Parsed::Error => self.parse_buf.clear(),
            }
        }
    }

    /// Wait for the next event. `timeout_ms` < 0 waits forever.
    /// Returns `None` on timeout.
    pub fn next_event(&mut self, timeout_ms: i32) -> Option<Event> {
        if let Some(ev) = self.pending.pop_front() {
            return Some(ev);
        }
        let deadline = if timeout_ms >= 0 {
            Some(std::time::Instant::now() + std::time::Duration::from_millis(timeout_ms as u64))
        } else {
            None
        };
        loop {
            let t = match deadline {
                Some(d) => {
                    let now = std::time::Instant::now();
                    if now >= d {
                        0
                    } else {
                        let ms = (d - now).as_micros().div_ceil(1000);
                        ms as c_int
                    }
                }
                None => -1,
            };
            let mut fds = [
                PollFd { fd: self.fd, events: POLLIN, revents: 0 },
                PollFd { fd: self.sig_r, events: POLLIN, revents: 0 },
            ];
            let nfds = if self.sig_r >= 0 { 2 } else { 1 };
            let r = unsafe { poll(fds.as_mut_ptr(), nfds, t) };
            if r < 0 {
                continue;
            }
            if r == 0 {
                if let Some(d) = deadline {
                    if std::time::Instant::now() >= d {
                        return None;
                    }
                }
                continue;
            }
            if nfds == 2 && fds[1].revents != 0 {
                let mut b = [0u8; 64];
                unsafe {
                    while read(self.sig_r, b.as_mut_ptr() as *mut c_void, b.len()) > 0 {}
                }
                return Some(Event::Resize);
            }
            if fds[0].revents != 0 {
                let mut buf = [0u8; TTY_BUFFER_SIZE];
                let n = unsafe { read(self.fd, buf.as_mut_ptr() as *mut c_void, TTY_BUFFER_SIZE) };
                if n <= 0 {
                    if n == 0 {
                        // end of input: behave as if nothing happens
                        std::thread::sleep(std::time::Duration::from_millis(10));
                    }
                    continue;
                }
                let n = n as usize;
                self.advance(&buf[..n], n == TTY_BUFFER_SIZE);
                if let Some(ev) = self.pending.pop_front() {
                    return Some(ev);
                }
            }
        }
    }
}

pub fn write_all(fd: i32, mut data: &[u8]) {
    while !data.is_empty() {
        let n = unsafe { write(fd, data.as_ptr() as *const c_void, data.len()) };
        if n <= 0 {
            return;
        }
        data = &data[n as usize..];
    }
}

fn fg_code(c: Color) -> &'static str {
    match c {
        Color::Reset => "\x1b[39m",
        Color::Red => "\x1b[38;5;1m",
        Color::Green => "\x1b[38;5;2m",
        Color::Magenta => "\x1b[38;5;5m",
    }
}

fn bg_code(c: Color) -> &'static str {
    match c {
        Color::Reset => "\x1b[49m",
        Color::Red => "\x1b[48;5;1m",
        Color::Green => "\x1b[48;5;2m",
        Color::Magenta => "\x1b[48;5;5m",
    }
}

fn modifier_diff(out: &mut Vec<u8>, from: u16, to: u16) {
    let removed = from & !to;
    if removed & BOLD != 0 {
        out.extend_from_slice(b"\x1b[22m");
        if to & DIM != 0 {
            out.extend_from_slice(b"\x1b[2m");
        }
    }
    if removed & ITALIC != 0 {
        out.extend_from_slice(b"\x1b[23m");
    }
    if removed & UNDERLINED != 0 {
        out.extend_from_slice(b"\x1b[24m");
    }
    if removed & DIM != 0 {
        out.extend_from_slice(b"\x1b[22m");
    }
    let added = to & !from;
    if added & BOLD != 0 {
        out.extend_from_slice(b"\x1b[1m");
    }
    if added & ITALIC != 0 {
        out.extend_from_slice(b"\x1b[3m");
    }
    if added & UNDERLINED != 0 {
        out.extend_from_slice(b"\x1b[4m");
    }
    if added & DIM != 0 {
        out.extend_from_slice(b"\x1b[2m");
    }
}

pub struct Terminal {
    buffers: [Buffer; 2],
    current: usize,
    viewport: Rect,
    out: Vec<u8>,
}

impl Terminal {
    pub fn new() -> Terminal {
        let (w, h) = size();
        let area = Rect::new(0, 0, w, h);
        Terminal { buffers: [Buffer::empty(area), Buffer::empty(area)], current: 0, viewport: area, out: Vec::new() }
    }

    pub fn write_raw(&mut self, s: &[u8]) {
        self.out.extend_from_slice(s);
        self.flush_out();
    }

    fn flush_out(&mut self) {
        if !self.out.is_empty() {
            write_all(1, &self.out);
            self.out.clear();
        }
    }

    fn autoresize(&mut self) {
        let (w, h) = size();
        let area = Rect::new(0, 0, w, h);
        if area != self.viewport {
            self.buffers[self.current].resize(area);
            self.buffers[1 - self.current].resize(area);
            self.viewport = area;
            self.out.extend_from_slice(b"\x1b[2J");
            self.flush_out();
            self.buffers[1 - self.current].reset();
        }
    }

    pub fn draw<F: FnOnce(&mut Buffer, Rect)>(&mut self, f: F) {
        self.autoresize();
        let area = self.viewport;
        {
            let buf = &mut self.buffers[self.current];
            f(buf, area);
        }
        // flush the differences
        let prev = &self.buffers[1 - self.current];
        let next = &self.buffers[self.current];
        let updates = prev.diff(next);
        let mut out = std::mem::take(&mut self.out);
        draw_cells(&mut out, &updates);
        out.extend_from_slice(b"\x1b[39m\x1b[49m\x1b[0m");
        out.extend_from_slice(b"\x1b[?25l");
        self.out = out;
        self.buffers[1 - self.current].reset();
        self.current = 1 - self.current;
        self.flush_out();
    }
}

fn draw_cells(out: &mut Vec<u8>, content: &[(u16, u16, &Cell)]) {
    let mut fg = Color::Reset;
    let mut bg = Color::Reset;
    let mut modifier: u16 = 0;
    let mut last_pos: Option<(u16, u16)> = None;
    for &(x, y, cell) in content {
        let contiguous = matches!(last_pos, Some(p) if x == p.0.wrapping_add(1) && y == p.1);
        if !contiguous {
            out.extend_from_slice(format!("\x1b[{};{}H", y as u32 + 1, x as u32 + 1).as_bytes());
        }
        last_pos = Some((x, y));
        if cell.modifier != modifier {
            modifier_diff(out, modifier, cell.modifier);
            modifier = cell.modifier;
        }
        if cell.fg != fg {
            out.extend_from_slice(fg_code(cell.fg).as_bytes());
            fg = cell.fg;
        }
        if cell.bg != bg {
            out.extend_from_slice(bg_code(cell.bg).as_bytes());
            bg = cell.bg;
        }
        out.extend_from_slice(cell.symbol.as_bytes());
    }
}
