            self.decrement_cursor();
        }
    }

    pub fn has_started(&self) -> bool {
        self.started_at.is_some()
    }

    pub fn has_finished(&self) -> bool {
        (self.input.len() == self.prompt.len())
            || (self.seconds_remaining.is_some() && self.seconds_remaining.unwrap() <= 0.0)
    }

    pub fn calc_results(&mut self) {
        let started_at = match self.started_at {
            Some(s) => s,
            None => return,
        };
        let correct_chars: Vec<&Input> = self.input.iter().filter(|i| i.outcome == Outcome::Correct).collect();

        let elapsed_ms = started_at.elapsed().as_millis() as f64;
        let whole_second_limit = elapsed_ms.floor();

        let mut map: HashMap<String, usize> = HashMap::new();
        for i in &correct_chars {
            let mut num_secs = i.timestamp.saturating_duration_since(started_at).as_secs_f64();
            if num_secs == 0.0 {
                num_secs = 1.0;
            } else if num_secs.ceil() <= whole_second_limit {
                if num_secs > 0.0 && num_secs < 1.0 {
                    num_secs = 1.0;
                } else {
                    num_secs = num_secs.ceil();
                }
            } else {
                num_secs = elapsed_ms;
            }
            *map.entry(num_secs.to_string()).or_insert(0) += 1;
        }
        let mut per_sec: Vec<(f64, f64)> =
            map.into_iter().map(|(k, v)| (k.parse::<f64>().unwrap(), v as f64)).collect();
        per_sec.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

        let intervals: Vec<f64> = per_sec
            .iter()
            .enumerate()
            .filter(|&(i, _)| i + 1 < per_sec.len())
            .map(|(_, x)| x.1)
            .collect();
        self.std_dev = if intervals.is_empty() { 0.0 } else { std_dev(&intervals) };

        let mut pressed = 0.0;
        self.wpm_coords.clear();
        for x in per_sec {
            pressed += x.1;
            self.wpm_coords.push((x.0, ((60.00 / x.0) * pressed) / 5.0));
        }

        self.wpm = match self.wpm_coords.last() {
            Some(c) => c.1.ceil(),
            None => 0.0,
        };
        self.accuracy = ((correct_chars.len() as f64 / self.input.len() as f64) * 100.0).round();
        if self.accuracy.is_nan() {
            self.accuracy = 0.0;
        }

        let _ = self.save_results(elapsed_ms / 1000.0);
    }

    fn save_results(&self, elapsed_secs: f64) -> std::io::Result<()> {
        let config_dir = match crate::dirs::config_dir() {
            Some(d) => d.join("thokr"),
            None => return Ok(()),
        };
        std::fs::create_dir_all(&config_dir)?;
        let log_path = config_dir.join("log.csv");
        let needs_header = !log_path.exists();
        let mut f = std::fs::OpenOptions::new().append(true).create(true).open(&log_path)?;
        let mut s = String::new();
        if needs_header {
            s.push_str("date,num_words,num_secs,elapsed_secs,wpm,accuracy,std_dev\n");
        }
        let num_secs = match self.number_of_secs {
            Some(n) => format!("{:.2}", n),
            None => String::new(),
        };
        s.push_str(&format!(
            "{},{},{},{:.2},{},{},{:.2}\n",
            crate::dirs::local_time_string(),
            self.number_of_words,
            num_secs,
            elapsed_secs,
            self.wpm,
            self.accuracy,
            self.std_dev
        ));
        f.write_all(s.as_bytes())?;
        Ok(())
    }
}

fn std_dev(data: &[f64]) -> f64 {
    let n = data.len() as f64;
    let mean = data.iter().sum::<f64>() / n;
    let variance = data
        .iter()
        .map(|v| {
            let d = mean - *v;
            d * d
        })
        .sum::<f64>()
        / n;
    variance.sqrt()
}
