//! Command line parsing.

use std::ffi::{OsStr, OsString};
use std::os::unix::ffi::OsStrExt;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Language {
    English,
    English1k,
    English10k,
}

#[derive(Clone, Debug)]
pub struct Cli {
    pub number_of_words: usize,
    pub number_of_sentences: Option<usize>,
    pub number_of_secs: Option<usize>,
    pub prompt: Option<String>,
    pub supported_language: Language,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Sty {
    None,
    Good,
    Warning,
    Error,
}

struct Colorizer {
    pieces: Vec<(String, Sty)>,
}

impl Colorizer {
    fn new() -> Colorizer {
        Colorizer { pieces: Vec::new() }
    }
    fn none<S: Into<String>>(&mut self, s: S) {
        self.pieces.push((s.into(), Sty::None));
    }
    fn good<S: Into<String>>(&mut self, s: S) {
        self.pieces.push((s.into(), Sty::Good));
    }
    fn warning<S: Into<String>>(&mut self, s: S) {
        self.pieces.push((s.into(), Sty::Warning));
    }
    fn error<S: Into<String>>(&mut self, s: S) {
        self.pieces.push((s.into(), Sty::Error));
    }
    fn render(&self, color: bool) -> Vec<u8> {
        let mut out = Vec::new();
        for (text, sty) in &self.pieces {
            if color {
                out.extend_from_slice(b"\x1b[0m");
                match sty {
                    Sty::None => {}
                    Sty::Good => out.extend_from_slice(b"\x1b[32m"),
                    Sty::Warning => out.extend_from_slice(b"\x1b[33m"),
                    Sty::Error => out.extend_from_slice(b"\x1b[1m\x1b[31m"),
                }
            }
            out.extend_from_slice(text.as_bytes());
            if color {
                out.extend_from_slice(b"\x1b[0m");
            }
        }
        out
    }
}

fn env_allows_color() -> bool {
    match std::env::var_os("TERM") {
        None => return false,
        Some(k) => {
            if k == "dumb" {
                return false;
            }
        }
    }
    if std::env::var_os("NO_COLOR").is_some() {
        return false;
    }
    true
}

fn emit(c: &Colorizer, to_stderr: bool, code: i32) -> ! {
    let fd = if to_stderr { 2 } else { 1 };
    let color = crate::term::is_tty(fd) && env_allows_color();
    let bytes = c.render(color);
    crate::term::write_all(fd, &bytes);
    std::process::exit(code);
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Id {
    Help,
    Version,
    Words,
    Secs,
    Sentences,
    Prompt,
    Language,
}

struct ArgDef {
    id: Id,
    short: char,
    long: &'static str,
    value_name: Option<&'static str>,
    possible: &'static [&'static str],
}

const LANGS: &[&str] = &["english", "english1k", "english10k"];

const ARGS: &[ArgDef] = &[
    ArgDef { id: Id::Help, short: 'h', long: "help", value_name: None, possible: &[] },
    ArgDef { id: Id::Version, short: 'V', long: "version", value_name: None, possible: &[] },
    ArgDef { id: Id::Words, short: 'w', long: "number-of-words", value_name: Some("NUMBER_OF_WORDS"), possible: &[] },
    ArgDef { id: Id::Secs, short: 's', long: "number-of-secs", value_name: Some("NUMBER_OF_SECS"), possible: &[] },
    ArgDef {
        id: Id::Sentences,
        short: 'f',
        long: "full-sentences",
        value_name: Some("NUMBER_OF_SENTENCES"),
        possible: &[],
    },
    ArgDef { id: Id::Prompt, short: 'p', long: "prompt", value_name: Some("PROMPT"), possible: &[] },
    ArgDef {
        id: Id::Language,
        short: 'l',
        long: "supported-language",
        value_name: Some("SUPPORTED_LANGUAGE"),
        possible: LANGS,
    },
];

fn def(id: Id) -> &'static ArgDef {
    ARGS.iter().find(|a| a.id == id).unwrap()
}

fn arg_display(a: &ArgDef) -> String {
    match a.value_name {
        Some(v) => format!("--{} <{}>", a.long, v),
        None => format!("--{}", a.long),
    }
}

struct Matched {
    id: Id,
    occurs: usize,
    groups: Vec<Vec<OsString>>,
}

struct Parser {
    bin_name: String,
    matcher: Vec<Matched>,
}

impl Parser {
    fn entry(&mut self, id: Id) -> &mut Matched {
        if let Some(pos) = self.matcher.iter().position(|m| m.id == id) {
            &mut self.matcher[pos]
        } else {
            self.matcher.push(Matched { id, occurs: 0, groups: Vec::new() });
            self.matcher.last_mut().unwrap()
        }
    }

    fn inc_occurrence(&mut self, id: Id) {
        self.entry(id).occurs += 1;
    }

    fn usage(&self, used: &[Id]) -> String {
        if used.is_empty() {
            format!("{} [OPTIONS]", self.bin_name)
        } else {
            let mut s = self.bin_name.clone();
            let mut seen: Vec<String> = Vec::new();
            for id in used {
                let d = arg_display(def(*id));
                if !seen.contains(&d) {
                    s.push(' ');
                    s.push_str(&d);
                    seen.push(d);
                }
            }
            s
        }
    }

    fn usage_with_title(&self, used: &[Id]) -> String {
        format!("USAGE:\n    {}", self.usage(used))
    }

    fn used_ids(&self) -> Vec<Id> {
        self.matcher.iter().map(|m| m.id).collect()
    }
}

fn start_error(c: &mut Colorizer, msg: &str) {
    c.error("error:");
    c.none(" ");
    c.none(msg);
}

fn put_usage(c: &mut Colorizer, usage: String) {
    c.none("\n\n");
    c.none(usage);
}

fn try_help(c: &mut Colorizer) {
    c.none("\n\nFor more information try ");
    c.good("--help");
    c.none("\n");
}

fn err_unknown_argument(arg: &str, did_you_mean: Option<&str>, usage: String) -> ! {
    let mut c = Colorizer::new();
    start_error(&mut c, "Found argument '");
    c.warning(arg);
    c.none("' which wasn't expected, or isn't valid in this context");
    if let Some(flag) = did_you_mean {
        c.none("\n\n\tDid you mean '");
        c.good(format!("--{}", flag));
        c.none("'?");
    }
    if arg.starts_with('-') {
        c.none(format!("\n\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`", arg, arg));
    }
    put_usage(&mut c, usage);
    try_help(&mut c);
    emit(&c, true, 2)
}

fn err_too_many_values(val: &str, arg: &str, usage: String) -> ! {
    let mut c = Colorizer::new();
    start_error(&mut c, "The value '");
    c.warning(val);
    c.none("' was provided to '");
    c.warning(arg);
    c.none("' but it wasn't expecting any more values");
    put_usage(&mut c, usage);
    try_help(&mut c);
    emit(&c, true, 2)
}

fn possible_values_list(c: &mut Colorizer, vals: &[&str]) {
    c.none("\n\t[possible values: ");
    if let Some((last, elements)) = vals.split_last() {
        for v in elements {
            c.good(*v);
            c.none(", ");
        }
        c.good(*last);
    }
    c.none("]");
}

fn err_empty_value(a: &ArgDef, usage: String) -> ! {
    let mut c = Colorizer::new();
    start_error(&mut c, "The argument '");
    c.warning(arg_display(a));
    c.none("' requires a value but none was supplied");
    if !a.possible.is_empty() {
        possible_values_list(&mut c, a.possible);
    }
    put_usage(&mut c, usage);
    try_help(&mut c);
    emit(&c, true, 2)
}

fn err_invalid_value(bad: &str, a: &ArgDef, usage: String) -> ! {
    let mut c = Colorizer::new();
    let suffix = did_you_mean(bad, a.possible.iter().copied()).pop();
    start_error(&mut c, &format!("{:?}", bad));
    c.none(" isn't a valid value for '");
    c.warning(arg_display(a));
    c.none("'");
    possible_values_list(&mut c, a.possible);
    if let Some(val) = suffix {
        c.none("\n\n\tDid you mean ");
        c.good(format!("{:?}", val));
        c.none("?");
    }
    put_usage(&mut c, usage);
    try_help(&mut c);
    emit(&c, true, 2)
}

fn err_value_validation(a: &ArgDef, val: &str, err: String) -> ! {
    let mut c = Colorizer::new();
    start_error(&mut c, "Invalid value ");
    c.warning(format!("{:?}", val));
    c.none(" for '");
    c.warning(arg_display(a));
    c.none("': ");
    c.none(err);
    try_help(&mut c);
    emit(&c, true, 2)
}

fn err_multiple(a: &ArgDef, usage: String) -> ! {
    let mut c = Colorizer::new();
    start_error(&mut c, "The argument '");
    c.warning(arg_display(a));
    c.none("' was provided more than once, but cannot be used multiple times");
    put_usage(&mut c, usage);
    try_help(&mut c);
    emit(&c, true, 2)
}

fn err_invalid_utf8(usage: String) -> ! {
    let mut c = Colorizer::new();
    start_error(&mut c, "Invalid UTF-8 was detected in one or more arguments");
    put_usage(&mut c, usage);
    try_help(&mut c);
    emit(&c, true, 2)
}

/// Error used when the program cannot run because stdin is not a terminal.
pub fn exit_not_a_tty() -> ! {
    let mut c = Colorizer::new();
    start_error(&mut c, "stdin must be a tty");
    put_usage(&mut c, "USAGE:\n    thokr [OPTIONS]".to_string());
    try_help(&mut c);
    emit(&c, true, 2)
}

fn print_version() -> ! {
    let mut c = Colorizer::new();
    c.none("thokr 0.4.1\n");
    emit(&c, false, 0)
}

fn print_help(bin_name: &str) -> ! {
    let mut c = Colorizer::new();
    c.none("");
    c.none("");
    c.good("thokr");
    c.none(" ");
    c.none("0.4.1");
    c.none("\n");
    c.none("");
    c.none("sleek typing tui with visualized results and historical logging");
    c.none("\n");
    c.none("\n");
    c.warning("USAGE:");
    c.none("\n    ");
    c.none(format!("{} [OPTIONS]", bin_name));
    c.none("\n\n");
    c.warning("OPTIONS:\n");
    let entries: &[(&str, &str, Option<&str>, &[&str])] = &[
        ("-f", "--full-sentences", Some("<NUMBER_OF_SENTENCES>"), &["number of sentences to use in test"]),
        ("-h", "--help", None, &["Print help information"]),
        (
            "-l",
            "--supported-language",
            Some("<SUPPORTED_LANGUAGE>"),
            &[
                "language to pull words from [default: english] [possible values: english, english1k,",
                "english10k]",
            ],
        ),
        ("-p", "--prompt", Some("<PROMPT>"), &["custom prompt to use"]),
        ("-s", "--number-of-secs", Some("<NUMBER_OF_SECS>"), &["number of seconds to run test"]),
        ("-V", "--version", None, &["Print version information"]),
        ("-w", "--number-of-words", Some("<NUMBER_OF_WORDS>"), &["number of words to use in test [default: 15]"]),
    ];
    for (i, (short, long, val, help)) in entries.iter().enumerate() {
        if i > 0 {
            c.none("\n");
            c.none("\n");
        }
        c.none("    ");
        c.good(*short);
        c.none(", ");
        c.good(*long);
        if let Some(v) = val {
            c.none(" ");
            c.good(*v);
        }
        c.none("\n            ");
        for (j, line) in help.iter().enumerate() {
            if j > 0 {
                c.none("\n");
                c.none("            ");
            }
            c.none(*line);
        }
    }
    c.none("");
    c.none("");
    c.none("\n");
    emit(&c, false, 0)
}

/// Jaro-Winkler similarity.
fn jaro_winkler(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let a_len = a.len();
    let b_len = b.len();
    let jaro = if a_len == 0 && b_len == 0 {
        1.0
    } else if a_len == 0 || b_len == 0 {
        0.0
    } else if a_len == 1 && b_len == 1 {
        if a[0] == b[0] {
            1.0
        } else {
            0.0
        }
    } else {
        let search_range = (std::cmp::max(a_len, b_len) / 2) - 1;
        let mut b_consumed = vec![false; b_len];
        let mut matches = 0.0;
        let mut transpositions = 0.0;
        let mut b_match_index = 0;
        for (i, a_elem) in a.iter().enumerate() {
            let min_bound = if i > search_range { i - search_range } else { 0 };
            let max_bound = std::cmp::min(b_len - 1, i + search_range);
            for (j, b_elem) in b.iter().enumerate().take(max_bound + 1) {
                if min_bound <= j && a_elem == b_elem && !b_consumed[j] {
                    b_consumed[j] = true;
                    matches += 1.0;
                    if j < b_match_index {
                        transpositions += 1.0;
                    }
                    b_match_index = j;
                    break;
                }
            }
        }
        if matches == 0.0 {
            0.0
        } else {
            (1.0 / 3.0) * ((matches / a_len as f64) + (matches / b_len as f64) + ((matches - transpositions) / matches))
        }
    };
    let prefix_length = a.iter().zip(b.iter()).take_while(|(x, y)| x == y).count();
    let jw = jaro + (0.1 * prefix_length as f64 * (1.0 - jaro));
    if jw <= 1.0 {
        jw
    } else {
        1.0
    }
}

fn did_you_mean<'a, I: Iterator<Item = &'a str>>(v: &str, possible: I) -> Vec<String> {
    let mut candidates: Vec<(f64, String)> = possible
        .map(|pv| (jaro_winkler(v, pv), pv.to_owned()))
        .filter(|(confidence, _)| *confidence > 0.8)
        .collect();
    candidates.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    candidates.into_iter().map(|(_, pv)| pv).collect()
}

enum ParseState {
    ValuesDone,
    Opt(Id),
}

fn lossy(s: &[u8]) -> String {
    String::from_utf8_lossy(s).into_owned()
}

fn split_once_char(s: &[u8], c: char) -> &[u8] {
    let mut tmp = [0u8; 4];
    let needle = c.encode_utf8(&mut tmp).as_bytes();
    if needle.is_empty() || s.len() < needle.len() {
        return &[];
    }
    for i in 0..=(s.len() - needle.len()) {
        if &s[i..i + needle.len()] == needle {
            return &s[i + needle.len()..];
        }
    }
    &[]
}

impl Parser {
    /// Handles an option that takes a value; returns the new parse state.
    fn parse_opt(&mut self, attached: Option<&[u8]>, id: Id) -> ParseState {
        match attached {
            Some(fv) => {
                let v = if fv.first() == Some(&b'=') { &fv[1..] } else { fv };
                self.inc_occurrence(id);
                self.entry(id).groups.push(vec![OsStr::from_bytes(v).to_os_string()]);
                ParseState::ValuesDone
            }
            None => {
                self.inc_occurrence(id);
                self.entry(id).groups.push(Vec::new());
                ParseState::Opt(id)
            }
        }
    }
}

pub fn parse(args: Vec<OsString>) -> Cli {
    let mut it = args.into_iter();
    let bin_name = match it.next() {
        Some(a) => {
            let p = std::path::Path::new(&a);
            match p.file_name().and_then(|f| f.to_str()) {
                Some(s) => s.to_owned(),
                None => "thokr".to_owned(),
            }
        }
        None => "thokr".to_owned(),
    };
    let mut p = Parser { bin_name, matcher: Vec::new() };
    let raw: Vec<OsString> = it.collect();
    let mut state = ParseState::ValuesDone;
    let mut trailing = false;

    for arg_os in raw.iter() {
        let bytes = arg_os.as_bytes();
        if !trailing {
            if bytes.starts_with(b"--") {
                let long_arg = &bytes[2..];
                if long_arg.is_empty() {
                    trailing = true;
                    continue;
                }
                let (name, val) = match long_arg.iter().position(|&b| b == b'=') {
                    Some(i) => (&long_arg[..i], Some(&long_arg[i..])),
                    None => (long_arg, None),
                };
                let found = ARGS.iter().find(|a| a.long.as_bytes() == name);
                match found {
                    Some(a) => {
                        if a.value_name.is_some() {
                            state = p.parse_opt(val, a.id);
                            continue;
                        } else if let Some(rest) = val {
                            let used = p.used_ids();
                            let usage = p.usage(&used);
                            err_too_many_values(&lossy(rest), &arg_display(a), usage);
                        } else if a.id == Id::Help {
                            print_help(&p.bin_name);
                        } else {
                            print_version();
                        }
                    }
                    None => {
                        let name_s = lossy(name);
                        let longs = ARGS.iter().map(|a| a.long);
                        let suggestion = did_you_mean(&name_s, longs).pop();
                        if let Some(ref s) = suggestion {
                            if let Some(a) = ARGS.iter().find(|a| a.long == s) {
                                p.inc_occurrence(a.id);
                            }
                        }
                        let used = p.used_ids();
                        let usage = p.usage_with_title(&used);
                        err_unknown_argument(&format!("--{}", name_s), suggestion.as_deref(), usage);
                    }
                }
            } else if bytes.starts_with(b"-") && bytes.len() != 1 {
                let short_arg = &bytes[1..];
                let s = lossy(short_arg);
                let mut handled = false;
                for c in s.chars() {
                    match ARGS.iter().find(|a| a.short == c) {
                        Some(a) => {
                            if a.value_name.is_none() {
                                if a.id == Id::Help {
                                    print_help(&p.bin_name);
                                } else {
                                    print_version();
                                }
                            }
                            let val = split_once_char(short_arg, c);
                            let val = if val.is_empty() { None } else { Some(val) };
                            state = p.parse_opt(val, a.id);
                            handled = true;
                            break;
                        }
                        None => {
                            let usage = p.usage_with_title(&[]);
                            err_unknown_argument(&format!("-{}", c), None, usage);
                        }
                    }
                }
                if handled {
                    continue;
                }
            }
            if let ParseState::Opt(id) = state {
                p.entry(id).groups.last_mut().unwrap().push(arg_os.clone());
                state = ParseState::ValuesDone;
                continue;
            }
        }
        // no positional arguments are accepted
        let usage = p.usage_with_title(&[]);
        err_unknown_argument(&lossy(bytes), None, usage);
    }

    // validation
    if let ParseState::Opt(id) = state {
        let should_err = match p.matcher.iter().find(|m| m.id == id) {
            Some(m) => m.groups.iter().all(|g| g.is_empty()),
            None => true,
        };
        if should_err {
            let usage = p.usage_with_title(&[]);
            err_empty_value(def(id), usage);
        }
    }

    let explicit: Vec<Id> = p.used_ids();
    for m in &p.matcher {
        let a = def(m.id);
        for v in m.groups.iter().flatten() {
            let vs = match v.to_str() {
                Some(s) => s,
                None => err_invalid_utf8(p.usage_with_title(&[])),
            };
            if !a.possible.is_empty() && !a.possible.contains(&vs) {
                err_invalid_value(vs, a, p.usage_with_title(&explicit));
            }
            match m.id {
                Id::Words | Id::Secs | Id::Sentences => {
                    if let Err(e) = vs.parse::<usize>() {
                        err_value_validation(a, vs, e.to_string());
                    }
                }
                _ => {}
            }
        }
        if m.occurs > 1 {
            err_multiple(a, p.usage_with_title(&[]));
        }
    }

    let get = |id: Id| -> Option<String> {
        p.matcher
            .iter()
            .find(|m| m.id == id)
            .and_then(|m| m.groups.iter().flatten().last())
            .map(|v| v.to_string_lossy().into_owned())
    };
    let number_of_words = get(Id::Words).map(|v| v.parse::<usize>().unwrap()).unwrap_or(15);
    let number_of_secs = get(Id::Secs).map(|v| v.parse::<usize>().unwrap());
    let number_of_sentences = get(Id::Sentences).map(|v| v.parse::<usize>().unwrap());
    let prompt = get(Id::Prompt);
    let supported_language = match get(Id::Language).as_deref() {
        Some("english1k") => Language::English1k,
        Some("english10k") => Language::English10k,
        _ => Language::English,
    };
    Cli { number_of_words, number_of_sentences, number_of_secs, prompt, supported_language }
}
