//! Rendering of the typing test and of the results screen.

use crate::thok::{Outcome, Thok};
use crate::tui::{
    layout_vertical, render_paragraph, Alignment, Axis, Buffer, Chart, Color, Constraint, Dataset, Rect, Span,
    Style, BOLD, DIM, ITALIC, UNDERLINED,
};
use crate::unicode::str_width;

const HORIZONTAL_MARGIN: u16 = 5;
const VERTICAL_MARGIN: u16 = 2;

struct Styles {
    bold: Style,
    green_bold: Style,
    red_bold: Style,
    dim_bold: Style,
    underlined_dim_bold: Style,
    italic: Style,
    magenta: Style,
}

fn styles() -> Styles {
    let bold = Style::new().add_modifier(BOLD);
    let green_bold = Style::new().patch(bold).fg(Color::Green);
    let red_bold = Style::new().patch(bold).fg(Color::Red);
    let dim_bold = Style::new().patch(bold).add_modifier(DIM);
    let underlined_dim_bold = Style::new().patch(dim_bold).add_modifier(UNDERLINED);
    let italic = Style::new().add_modifier(ITALIC);
    let magenta = Style::new().fg(Color::Magenta);
    Styles { bold, green_bold, red_bold, dim_bold, underlined_dim_bold, italic, magenta }
}

pub fn draw(thok: &Thok, buf: &mut Buffer, area: Rect) {
    if !thok.has_finished() {
        draw_prompt(thok, buf, area);
    } else {
        draw_results(thok, buf, area);
    }
}

fn draw_prompt(thok: &Thok, buf: &mut Buffer, area: Rect) {
    let st = styles();
    let max_chars_per_line = area.width.wrapping_sub(HORIZONTAL_MARGIN * 2);
    let prompt_width = str_width(&thok.prompt);
    let mut prompt_occupied_lines = ((prompt_width as f64 / max_chars_per_line as f64).ceil() + 1.0) as u16;
    let time_left_lines = if thok.number_of_secs.is_some() { 2 } else { 0 };
    if prompt_width <= max_chars_per_line as usize {
        prompt_occupied_lines = 1;
    }
    let pad = ((area.height as f64 - prompt_occupied_lines as f64) / 2.0) as u16;
    let chunks = layout_vertical(
        area,
        HORIZONTAL_MARGIN,
        0,
        &[
            Constraint::Length(pad),
            Constraint::Length(time_left_lines),
            Constraint::Length(prompt_occupied_lines),
            Constraint::Length(pad),
        ],
    );

    let mut spans: Vec<Span> = thok
        .input
        .iter()
        .enumerate()
        .map(|(idx, input)| {
            let expected = thok.get_expected_char(idx).to_string();
            match input.outcome {
                Outcome::Incorrect => Span::styled(
                    match expected.as_str() {
                        " " => "\u{b7}".to_owned(),
                        _ => expected,
                    },
                    st.red_bold,
                ),
                Outcome::Correct => Span::styled(expected, st.green_bold),
            }
        })
        .collect();

    spans.push(Span::styled(thok.get_expected_char(thok.cursor_pos).to_string(), st.underlined_dim_bold));
    let rest = remaining_prompt(thok);
    spans.push(Span::styled(rest, st.dim_bold));

    let alignment = if prompt_occupied_lines == 1 { Alignment::Center } else { Alignment::Left };
    render_paragraph(buf, chunks[2], &spans, alignment, Some(true));

    if thok.number_of_secs.is_some() {
        let timer = Span::styled(format!("{:.1}", thok.seconds_remaining.unwrap()), st.dim_bold);
        render_paragraph(buf, chunks[1], &[timer], Alignment::Center, None);
    }
}

// The part of the prompt following the cursor.
#[rustfmt::skip]
fn remaining_prompt(thok: &Thok) -> String {
    let text = &thok.prompt; let end = text.len(); let r = &thok.prompt[(thok.cursor_pos + 1)..end];
    r.to_string()
}

fn draw_results(thok: &Thok, buf: &mut Buffer, area: Rect) {
    let st = styles();
    let chunks = layout_vertical(
        area,
        HORIZONTAL_MARGIN,
        VERTICAL_MARGIN,
        &[Constraint::Min(1), Constraint::Length(1), Constraint::Length(1), Constraint::Length(1)],
    );

    let mut highest_wpm = 0.0;
    for ts in &thok.wpm_coords {
        if ts.1 > highest_wpm {
            highest_wpm = ts.1;
        }
    }
    let x_max = match thok.wpm_coords.last() {
        Some(c) if c.0 >= 1.0 => c.0,
        _ => 1.0,
    };
    let y_max: f64 = highest_wpm.round();

    let chart = Chart {
        x_axis: Axis {
            title: Some(Span::raw("seconds")),
            bounds: [1.0, x_max],
            labels: Some(vec![Span::styled("1", st.bold), Span::styled(format!("{:.2}", x_max), st.bold)]),
        },
        y_axis: Axis {
            title: Some(Span::raw("wpm")),
            bounds: [0.0, y_max],
            labels: Some(vec![Span::styled("0", st.bold), Span::styled(format!("{}", y_max), st.bold)]),
        },
        datasets: vec![Dataset { name: String::new(), data: &thok.wpm_coords, color: st.magenta.fg.unwrap() }],
    };
    chart.render(chunks[0], buf);

    let stats = Span::styled(
        format!("{} wpm   {}% acc   {:.2} sd", thok.wpm, thok.accuracy, thok.std_dev),
        st.bold,
    );
    render_paragraph(buf, chunks[1], &[stats], Alignment::Center, None);

    let legend = Span::styled("(r)etry / (n)ew / (esc)ape", st.italic);
    render_paragraph(buf, chunks[3], &[legend], Alignment::Left, None);
}
