//! Word lists used to generate prompts.

use crate::cli::Language;
use crate::rng::Rng;

static ENGLISH: &str = include_str!("../data/english.txt");
static ENGLISH_1K: &str = include_str!("../data/english1k.txt");
static ENGLISH_10K: &str = include_str!("../data/english10k.txt");

fn words(lang: Language) -> Vec<&'static str> {
    let src = match lang {
        Language::English => ENGLISH,
        Language::English1k => ENGLISH_1K,
        Language::English10k => ENGLISH_10K,
    };
    src.lines().filter(|l| !l.is_empty()).collect()
}

/// A prompt made of `n` distinct random entries of the word list.
pub fn random_words(lang: Language, n: usize, rng: &mut Rng) -> String {
    let list = words(lang);
    let chosen = rng.choose_multiple(&list, n);
    chosen.iter().map(|s| **s).collect::<Vec<&str>>().join(" ")
}
