mod cli;
mod dirs;
mod lang;
mod rng;
mod sentence;
mod tables;
mod term;
mod thok;
mod tui;
mod ui;
mod unicode;

use std::time::{Duration, Instant};

use cli::Cli;
use term::{Event, KeyCode, MOD_CONTROL};
use thok::Thok;

const TICK_RATE_MS: u64 = 100;

struct App {
    cli: Cli,
    thok: Thok,
    rng: rng::Rng,
}

impl App {
    fn new(cli: Cli) -> App {
        let mut rng = rng::Rng::new();
        let prompt = match &cli.prompt {
            Some(p) => p.clone(),
            None => new_prompt(&cli, &mut rng),
        };
        let thok = Thok::new(prompt, cli.number_of_words, cli.number_of_secs.map(|s| s as f64));
        App { cli, thok, rng }
    }

    fn reset(&mut self, new_prompt: Option<String>) {
        let prompt = match new_prompt {
            Some(p) => p,
            None => self.thok.prompt.clone(),
        };
        self.thok = Thok::new(prompt, self.cli.number_of_words, self.cli.number_of_secs.map(|s| s as f64));
    }
}

fn new_prompt(cli: &Cli, rng: &mut rng::Rng) -> String {
    match cli.number_of_sentences {
        Some(n) => sentence::sentences(n, rng),
        None => lang::random_words(cli.supported_language, cli.number_of_words, rng),
    }
}

enum ExitType {
    Restart,
    New,
    Quit,
}

fn run(terminal: &mut term::Terminal, input: &mut term::Input, app: &mut App) {
    let should_tick = app.cli.number_of_secs.unwrap_or(0) > 0;
    let tick = Duration::from_millis(TICK_RATE_MS);
    let mut next_tick = Instant::now() + tick;
    loop {
        let mut exit_type = ExitType::Quit;
        terminal.draw(|buf, area| ui::draw(&app.thok, buf, area));
        loop {
            let event = if should_tick {
                let now = Instant::now();
                if now >= next_tick {
                    next_tick += tick;
                    if next_tick < now {
                        next_tick = now + tick;
                    }
                    None
                } else {
                    let ms = (next_tick - now).as_micros().div_ceil(1000) as i32;
                    match input.next_event(ms) {
                        Some(e) => Some(e),
                        None => continue,
                    }
                }
            } else {
                input.next_event(-1)
            };
            match event {
                None => {
                    // tick
                    if app.thok.has_started() && !app.thok.has_finished() {
                        app.thok.on_tick();
                        if app.thok.has_finished() {
                            app.thok.calc_results();
                        }
                        terminal.draw(|buf, area| ui::draw(&app.thok, buf, area));
                    }
                }
                Some(Event::Resize) => {
                    terminal.draw(|buf, area| ui::draw(&app.thok, buf, area));
                }
                Some(Event::Other) => {}
                Some(Event::Key(key)) => {
                    match key.code {
                        KeyCode::Esc => break,
                        KeyCode::Backspace => {
                            if !app.thok.has_finished() {
                                app.thok.backspace();
                            }
                        }
                        KeyCode::Left => {
                            exit_type = ExitType::Restart;
                            break;
                        }
                        KeyCode::Right => {
                            exit_type = ExitType::New;
                            break;
                        }
                        KeyCode::Char(c) => {
                            if key.modifiers & MOD_CONTROL != 0 && c == 'c' {
                                break;
                            }
                            if !app.thok.has_finished() {
                                app.thok.write(c);
                                if app.thok.has_finished() {
                                    app.thok.calc_results();
                                }
                            } else {
                                match c {
                                    'r' => {
                                        exit_type = ExitType::Restart;
                                        break;
                                    }
                                    'n' => {
                                        exit_type = ExitType::New;
                                        break;
                                    }
                                    _ => {}
                                }
                            }
                        }
                        _ => {}
                    }
                    terminal.draw(|buf, area| ui::draw(&app.thok, buf, area));
                }
            }
        }
        match exit_type {
            ExitType::Restart => app.reset(None),
            ExitType::New => {
                let p = new_prompt(&app.cli, &mut app.rng);
                app.reset(Some(p));
            }
            ExitType::Quit => break,
        }
    }
}

fn main() {
    let cli = cli::parse(std::env::args_os().collect());
    if !term::is_tty(0) {
        cli::exit_not_a_tty();
    }
    let saved = term::enable_raw_mode(0);
    let mut terminal = term::Terminal::new();
    terminal.write_raw(b"\x1b[?1049h");
    let mut terminal = terminal;
    let mut input = term::Input::new(0);
    let mut app = App::new(cli);
    run(&mut terminal, &mut input, &mut app);
    if let Some(t) = saved {
        term::restore_mode(0, &t);
    }
    terminal.write_raw(b"\x1b[?1049l");
    terminal.write_raw(b"\x1b[?25h");
}
