//! Random grammatical sentence generator used by `--full-sentences`.

use crate::rng::Rng;

static OPINION: &str = include_str!("../data/sentence/opinion.txt");
static SIZE: &str = include_str!("../data/sentence/size.txt");
static AGE: &str = include_str!("../data/sentence/age.txt");
static COLOR: &str = include_str!("../data/sentence/color.txt");
static MATERIAL: &str = include_str!("../data/sentence/material.txt");
static ADVERB: &str = include_str!("../data/sentence/adverb.txt");
static NOUN: &str = include_str!("../data/sentence/noun.txt");
static VERB: &str = include_str!("../data/sentence/verb.txt");

fn list(src: &'static str) -> Vec<&'static str> {
    src.lines().filter(|l| !l.is_empty()).collect()
}

struct Lexicon {
    adjectives: [Vec<&'static str>; 5],
    adverbs: Vec<&'static str>,
    nouns: Vec<(&'static str, bool)>,
    verbs: Vec<&'static str>,
}

impl Lexicon {
    fn load() -> Lexicon {
        let mut nouns: Vec<(&'static str, bool)> = list(NOUN).into_iter().map(|n| (n, false)).collect();
        // these nouns also exist with an irregular plural form
        nouns.push(("man", true));
        nouns.push(("woman", true));
        Lexicon {
            adjectives: [list(OPINION), list(SIZE), list(AGE), list(COLOR), list(MATERIAL)],
            adverbs: list(ADVERB),
            nouns,
            verbs: list(VERB),
        }
    }
}

fn pluralize(noun: &str, irregular: bool) -> String {
    match noun {
        "goose" => return "geese".to_string(),
        "ox" => return "oxen".to_string(),
        "man" if irregular => return "men".to_string(),
        "woman" if irregular => return "women".to_string(),
        _ => {}
    }
    let b = noun.as_bytes();
    if b.len() >= 2 && noun.ends_with('y') && !b"aeiou".contains(&b[b.len() - 2]) {
        return format!("{}ies", &noun[..noun.len() - 1]);
    }
    if noun.ends_with("ss") {
        return format!("{}es", noun);
    }
    format!("{}s", noun)
}

fn third_person(verb: &str) -> String {
    if verb.ends_with('s') || verb.ends_with("sh") || verb.ends_with('x') {
        format!("{}es", verb)
    } else {
        format!("{}s", verb)
    }
}

/// Builds a noun phrase; returns the words and whether it is plural.
fn noun_phrase(lex: &Lexicon, rng: &mut Rng, out: &mut Vec<String>) -> bool {
    let plural = rng.chance(0.5);
    if !plural || rng.chance(0.5) {
        out.push("the".to_string());
    }
    let count = if rng.chance(0.5) { 1 } else { 2 };
    let mut cats: Vec<usize> = (0..count).map(|_| rng.below(5)).collect();
    cats.sort();
    for c in cats {
        out.push(rng.choose(&lex.adjectives[c]).to_string());
    }
    let &(noun, irregular) = rng.choose(&lex.nouns);
    if plural {
        out.push(pluralize(noun, irregular));
    } else {
        out.push(noun.to_string());
    }
    plural
}

fn sentence(lex: &Lexicon, rng: &mut Rng) -> String {
    let mut words: Vec<String> = Vec::new();
    let plural = noun_phrase(lex, rng, &mut words);

    let verb = rng.choose(&lex.verbs);
    let verb = if plural { verb.to_string() } else { third_person(verb) };
    let adverb_count = if rng.chance(0.5) { 1 } else { 2 };
    let adverbs: Vec<String> = (0..adverb_count).map(|_| rng.choose(&lex.adverbs).to_string()).collect();
    if rng.chance(0.5) {
        words.extend(adverbs);
        words.push(verb);
    } else {
        words.push(verb);
        words.extend(adverbs);
    }

    if rng.chance(0.5) {
        noun_phrase(lex, rng, &mut words);
    }

    let mut s = words.join(" ");
    if let Some(first) = s.chars().next() {
        let upper: String = first.to_uppercase().collect();
        s.replace_range(..first.len_utf8(), &upper);
    }
    s.push('.');
    s
}

/// `n` random sentences separated by spaces.
pub fn sentences(n: usize, rng: &mut Rng) -> String {
    let lex = Lexicon::load();
    let mut out = Vec::with_capacity(n);
    for _ in 0..n {
        out.push(sentence(&lex, rng));
    }
    out.join(" ")
}
